/**
 * Servicio para gestionar el estado y datos del menú del sidebar
 * Puede ser extendido para cargar menús dinámicos desde API
 */
import { Injectable, signal } from '@angular/core';
import { MenuItem } from '../../models/menu.interface';

@Injectable({
  providedIn: 'root'
})
export class SidebarService {
  /** Estado del sidebar (signal reactivo) */
  private _isCollapsed = signal(false);
  
  /** Getter público para el estado colapsado */
  get isCollapsed() {
    return this._isCollapsed.asReadonly();
  }

  /**
   * Verifica si estamos en el navegador (no en SSR)
   */
  private get isBrowser(): boolean {
    return typeof window !== 'undefined' && typeof localStorage !== 'undefined';
  }

  constructor() {
    // Cargar estado desde localStorage (solo en browser)
    if (this.isBrowser) {
      const savedState = localStorage.getItem('sidebarCollapsed');
      if (savedState !== null) {
        this._isCollapsed.set(savedState === 'true');
      }
    }
  }

  /**
   * Toggle del estado del sidebar
   */
  toggleSidebar(): void {
    this._isCollapsed.update(value => !value);
    if (this.isBrowser) {
      localStorage.setItem('sidebarCollapsed', this._isCollapsed().toString());
    }
  }

  /**
   * Establece el estado del sidebar
   * @param collapsed - Estado deseado
   */
  setSidebarState(collapsed: boolean): void {
    this._isCollapsed.set(collapsed);
    if (this.isBrowser) {
      localStorage.setItem('sidebarCollapsed', collapsed.toString());
    }
  }

  /**
   * Obtiene el menú (puede ser extendido para cargar desde API)
   * @returns Array de items del menú
   */
  getMenuItems(): MenuItem[] {
    // Aquí puedes hacer una llamada HTTP para cargar menú dinámico
    return [
      {
        id: 'dashboard',
        label: 'Dashboard',
        icon: 'dashboard',
        route: '/dashboard'
      },
      {
        id: 'empresas',
        label: 'Empresas',
        icon: 'business',
        route: '/empresas'
      },
      {
        id: 'categorias',
        label: 'Categorías',
        icon: 'category',
        route: '/categorias'
      },
      {
        id: 'productos',
        label: 'Productos',
        icon: 'inventory_2',
        route: '/productos'
      },
      {
        id: 'publicidad',
        label: 'Publicidad',
        icon: 'campaign',
        route: '/publicidad'
      },
      {
        id: 'reportes',
        label: 'Reportes',
        icon: 'assessment',
        children: [
          {
            id: 'reportes-ventas',
            label: 'Ventas',
            icon: 'show_chart',
            route: '/reportes/ventas'
          },
          {
            id: 'reportes-usuarios',
            label: 'Usuarios',
            icon: 'people',
            route: '/reportes/usuarios'
          }
        ]
      },
      {
        id: 'configuracion',
        label: 'Configuración',
        icon: 'settings',
        route: '/configuracion'
      }
    ];
  }

  /**
   * Filtra items del menú por roles de usuario
   * @param items - Items del menú
   * @param userRoles - Roles del usuario actual
   * @returns Items filtrados
   */
  filterMenuByRoles(items: MenuItem[], userRoles: string[]): MenuItem[] {
    return items.filter(item => {
      if (!item.roles || item.roles.length === 0) {
        return true;
      }
      return item.roles.some(role => userRoles.includes(role));
    }).map(item => {
      if (item.children) {
        return {
          ...item,
          children: this.filterMenuByRoles(item.children, userRoles)
        };
      }
      return item;
    });
  }
}
