import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatDividerModule } from '@angular/material/divider';
import { MatBadgeModule } from '@angular/material/badge';
import { AuthService } from '../../services/auth/auth.service';
import { SidebarService } from '../../services/sidebar/sidebar.service';

/**
 * Header Component (Topbar)
 * Barra superior con información del usuario y acciones
 */
@Component({
  selector: 'app-header',
  standalone: true,
  imports: [
    CommonModule,
    MatIconModule,
    MatButtonModule,
    MatMenuModule,
    MatDividerModule,
    MatBadgeModule
  ],
  templateUrl: './header.component.html',
  styleUrl: './header.component.scss'
})
export class HeaderComponent implements OnInit {
  /** Usuario actual */
  userName: string = '';
  userAvatar?: string;
  
  /** Estado del sidebar para ajustar el header */
  get isSidebarCollapsed() {
    return this.sidebarService.isCollapsed();
  }

  constructor(
    public authService: AuthService,
    private sidebarService: SidebarService
  ) {}

  ngOnInit(): void {
    // Cargar datos del usuario
    this.userName = this.authService.getFirstName();
    this.userAvatar = this.authService.getUserAvatar();
  }

  /**
   * Toggle del sidebar desde el header
   */
  toggleSidebar(): void {
    this.sidebarService.toggleSidebar();
  }

  /**
   * Navega al perfil del usuario
   */
  goToProfile(): void {
    // Implementar navegación al perfil
    console.log('Navegar a perfil');
  }

  /**
   * Navega a configuración
   */
  goToSettings(): void {
    // Implementar navegación a configuración
    console.log('Navegar a configuración');
  }

  /**
   * Cierra sesión
   */
  logout(): void {
    this.authService.logout();
    // Redirigir a login
    console.log('Cerrar sesión');
  }

  /**
   * Abre notificaciones
   */
  openNotifications(): void {
    // Implementar panel de notificaciones
    console.log('Abrir notificaciones');
  }
}
