/* src/app/components/sidebar/sidebar.component.scss */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: 260px;
  background:
    linear-gradient(
      180deg,
      #1a1a2e 0%,
      #16213e 100%);
  color: #ffffff;
  display: flex;
  flex-direction: column;
  z-index: 1000;
  box-shadow: 2px 0 8px rgba(0, 0, 0, 0.3);
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
}
.sidebar.collapsed {
  width: 70px;
}
.sidebar.collapsed .menu-label,
.sidebar.collapsed .submenu-label,
.sidebar.collapsed .expand-icon,
.sidebar.collapsed .logo-text,
.sidebar.collapsed .footer-text {
  opacity: 0;
  pointer-events: none;
}
.sidebar.collapsed .submenu {
  display: none;
}
.sidebar-header {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  flex-shrink: 0;
}
.logo-container {
  flex: 1;
  overflow: hidden;
}
.logo-full {
  display: flex;
  align-items: center;
  gap: 12px;
  animation: fadeIn 0.3s ease-in;
}
.logo-full .logo-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: #1976d2;
}
.logo-full .logo-text {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.5px;
  white-space: nowrap;
}
.logo-collapsed {
  display: flex;
  justify-content: center;
  animation: fadeIn 0.3s ease-in;
}
.logo-collapsed mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: #1976d2;
}
.toggle-btn {
  color: #b0b3b8;
  transition: all 0.2s ease;
}
.toggle-btn:hover {
  color: #ffffff;
  background-color: rgba(255, 255, 255, 0.08);
}
.sidebar-nav {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px 0;
}
.sidebar-nav::-webkit-scrollbar {
  width: 6px;
}
.sidebar-nav::-webkit-scrollbar-track {
  background: transparent;
}
.sidebar-nav::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}
.sidebar-nav::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}
.menu-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.menu-item {
  margin: 4px 8px;
}
.menu-link {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  border-radius: 8px;
  color: #b0b3b8;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  border: none;
  background: transparent;
  width: 100%;
  font-family: inherit;
  font-size: 14px;
}
.menu-link:hover:not(.disabled) {
  background-color: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}
.menu-link:hover:not(.disabled) .menu-icon {
  transform: scale(1.1);
}
.menu-link.active {
  background-color: rgba(25, 118, 210, 0.2);
  color: #1976d2;
  font-weight: 500;
}
.menu-link.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 70%;
  background-color: #1976d2;
  border-radius: 0 2px 2px 0;
}
.menu-link.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.menu-icon {
  flex-shrink: 0;
  font-size: 24px;
  width: 24px;
  height: 24px;
  transition: transform 0.2s ease;
}
.menu-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.expand-icon {
  flex-shrink: 0;
  font-size: 20px;
  width: 20px;
  height: 20px;
  transition: transform 0.2s ease, opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.submenu-trigger.expanded .expand-icon {
  transform: rotate(180deg);
}
.menu-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 600;
  background-color: #dc3545;
  color: white;
}
.menu-badge.badge-primary {
  background-color: #1976d2;
}
.menu-badge.badge-accent {
  background-color: #ff5722;
}
.menu-badge.badge-warn {
  background-color: #ffc107;
  color: #000;
}
.menu-item-with-children {
  position: relative;
}
.submenu {
  list-style: none;
  margin: 4px 0 0 0;
  padding: 0 0 0 40px;
  overflow: hidden;
  animation: slideDown 0.3s ease-out;
}
.submenu-item {
  margin: 2px 0;
}
.submenu-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-radius: 6px;
  color: #b0b3b8;
  text-decoration: none;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.submenu-link:hover:not(.disabled) {
  background-color: rgba(255, 255, 255, 0.08);
  color: #ffffff;
  padding-left: 20px;
}
.submenu-link.active {
  background-color: rgba(25, 118, 210, 0.15);
  color: #1976d2;
  font-weight: 500;
}
.submenu-link.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.submenu-icon {
  flex-shrink: 0;
  font-size: 20px;
  width: 20px;
  height: 20px;
}
.submenu-label {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sidebar-footer {
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  flex-shrink: 0;
  padding: 0 16px;
}
.footer-content {
  width: 100%;
  text-align: center;
}
.footer-text {
  font-size: 12px;
  color: #b0b3b8;
  transition: opacity 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.footer-icon {
  font-size: 20px;
  width: 20px;
  height: 20px;
  color: #b0b3b8;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes slideDown {
  from {
    opacity: 0;
    max-height: 0;
  }
  to {
    opacity: 1;
    max-height: 500px;
  }
}
@media (max-width: 768px) {
  .sidebar:not(.mobile-open) {
    transform: translateX(-100%);
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
  .sidebar-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
    display: none;
  }
  .sidebar-overlay.active {
    display: block;
  }
}
.menu-link:focus-visible,
.submenu-link:focus-visible {
  outline: 2px solid #1976d2;
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
/*# sourceMappingURL=sidebar.component.css.map */
