import { Component, OnInit, signal, Inject, Renderer2 } from '@angular/core';
import { CommonModule, DOCUMENT } from '@angular/common';
import { Router, RouterModule, NavigationEnd } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { filter } from 'rxjs/operators';
import { MenuItem } from '../../models/menu.interface';

/**
 * Sidebar Component
 * Componente standalone para navegación lateral con soporte para colapsar/expandir
 * y detección automática de ruta activa
 */
@Component({
  selector: 'app-sidebar',
  standalone: true,
  imports: [
    CommonModule,
    RouterModule,
    MatIconModule,
    MatButtonModule,
    MatTooltipModule
  ],
  templateUrl: './sidebar.component.html',
  styleUrl: './sidebar.component.scss'
})
export class SidebarComponent implements OnInit {
  /** Estado del sidebar (colapsado/expandido) usando Angular Signals */
  isCollapsed = signal(false);

  /** Ruta activa actual */
  activeRoute = signal('');

  /** Items del menú principal */
  menuItems: MenuItem[] = [
    {
      id: 'dashboard',
      label: 'Dashboard',
      icon: 'dashboard',
      route: '/dashboard'
    },
    {
      id: 'empresas',
      label: 'Empresas',
      icon: 'business',
      route: '/empresas'
    },
    {
      id: 'categorias',
      label: 'Categorías',
      icon: 'category',
      route: '/categorias'
    },
    {
      id: 'productos',
      label: 'Productos',
      icon: 'inventory_2',
      route: '/productos'
    },
    {
      id: 'publicidad',
      label: 'Publicidad',
      icon: 'campaign',
      route: '/publicidad'
    },
    {
      id: 'reportes',
      label: 'Reportes',
      icon: 'assessment',
      children: [
        {
          id: 'reportes-ventas',
          label: 'Ventas',
          icon: 'show_chart',
          route: '/reportes/ventas'
        },
        {
          id: 'reportes-usuarios',
          label: 'Usuarios',
          icon: 'people',
          route: '/reportes/usuarios'
        }
      ]
    },
    {
      id: 'configuracion',
      label: 'Configuración',
      icon: 'settings',
      route: '/configuracion'
    }
  ];

  constructor(
    private router: Router,
    @Inject(DOCUMENT) private document: Document,
    private renderer: Renderer2
  ) {
    // Escuchar cambios de ruta para actualizar item activo
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: any) => {
        this.activeRoute.set(event.urlAfterRedirects);
      });
  }

  ngOnInit(): void {
    // Establecer ruta inicial
    this.activeRoute.set(this.router.url);
    
    // Cargar estado del sidebar desde localStorage (persistencia)
    if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
      const savedState = localStorage.getItem('sidebarCollapsed');
      if (savedState !== null) {
        const collapsed = savedState === 'true';
        this.isCollapsed.set(collapsed);
        this.updateBodyClass(collapsed);
      }
    }
  }

  /**
   * Actualiza la clase del body para ajustar el layout
   */
  private updateBodyClass(collapsed: boolean): void {
    if (typeof window !== 'undefined') {
      if (collapsed) {
        this.renderer.addClass(this.document.body, 'sidebar-collapsed');
      } else {
        this.renderer.removeClass(this.document.body, 'sidebar-collapsed');
      }
    }
  }

  /**
   * Alterna el estado colapsado/expandido del sidebar
   */
  toggleSidebar(): void {
    this.isCollapsed.update(value => !value);
    const collapsed = this.isCollapsed();
    
    // Actualizar clase del body
    this.updateBodyClass(collapsed);
    
    // Persistir estado en localStorage
    if (typeof window !== 'undefined' && typeof localStorage !== 'undefined') {
      localStorage.setItem('sidebarCollapsed', collapsed.toString());
    }
  }

  /**
   * Navega a una ruta específica
   * @param item - Item del menú
   */
  navigateTo(item: MenuItem): void {
    if (item.disabled) return;

    if (item.route) {
      this.router.navigate([item.route]);
    } else if (item.children) {
      // Toggle del submenú
      item.expanded = !item.expanded;
    }
  }

  /**
   * Verifica si una ruta está activa
   * @param route - Ruta a verificar
   * @returns true si la ruta está activa
   */
  isActive(route?: string): boolean {
    if (!route) return false;
    return this.activeRoute().startsWith(route);
  }

  /**
   * Verifica si algún hijo del item está activo
   * @param item - Item con hijos
   * @returns true si algún hijo está activo
   */
  hasActiveChild(item: MenuItem): boolean {
    if (!item.children) return false;
    return item.children.some(child => this.isActive(child.route));
  }

  /**
   * Toggle de submenú
   * @param item - Item del menú
   * @param event - Evento del click
   */
  toggleSubmenu(item: MenuItem, event: Event): void {
    event.stopPropagation();
    if (item.children) {
      item.expanded = !item.expanded;
    }
  }

  /**
   * Verifica si el usuario tiene permisos para ver el item
   * @param item - Item del menú
   * @returns true si tiene permisos
   */
  hasPermission(item: MenuItem): boolean {
    // Implementación básica
    // Aquí puedes integrar tu servicio de autenticación
    if (!item.roles || item.roles.length === 0) {
      return true;
    }
    
    // Ejemplo:
    // const userRole = this.authService.getUserRole();
    // return item.roles.includes(userRole);
    
    return true; // Por defecto mostrar todos
  }

  /**
   * Obtiene el tooltip text para items colapsados
   * @param item - Item del menú
   * @returns Texto del tooltip
   */
  getTooltip(item: MenuItem): string {
    return this.isCollapsed() ? item.label : '';
  }
}
